/** A tone's colour, as SubstrateUI's tokens give it: Apple's system colour's value, light and dark. */
public fun ScreenTone.color(dark: Boolean): Color = when (this) {
    ScreenTone.quiet -> if (dark) Color(0xFF98989F) else Color(0xFF8A8A8E)
    ScreenTone.positive -> if (dark) Color(0xFF30D158) else Color(0xFF34C759)
    ScreenTone.informative -> if (dark) Color(0xFF0A84FF) else Color(0xFF007AFF)
    ScreenTone.supporting -> if (dark) Color(0xFF40CBE0) else Color(0xFF30B0C7)
    ScreenTone.caution -> if (dark) Color(0xFFFF9F0A) else Color(0xFFFF9500)
    ScreenTone.critical -> if (dark) Color(0xFFFF453A) else Color(0xFFFF3B30)
}

